const $wheelBtn = document.querySelector('.

wheel_btn');
const $wheelBlock = document.querySelector('.wheel_block');
const $tryCount = document.querySelector('.try_count');
const $popUp = document.querySelector('.pop_up');
const $spinBox = document.querySelector('.pop_up__box--spin');
const $formBox = document.querySelector('.pop_up__box--form');
const $btnAgin = document.querySelector('.pop_btn--agin');
let tryCount = 2;
let isSpin = false;

$wheelBtn.addEventListener('click', function (event) {
    if(!isSpin){
        $wheelBlock.classList.add('first');
        isSpin = true;
        $wheelBtn.classList.add('btn-dis');
        tryCount--;
        $tryCount.textContent = tryCount + '';
        setTimeout(function () {
            $popUp.classList.add('pop_up__open');
            $spinBox.classList.add('active');
        }, 3500)
    } else {

    }
});

$btnAgin.addEventListener('click', function (event) {
    $wheelBlock.classList.add('second');
    $popUp.classList.remove('pop_up__open');
    tryCount--;
    $tryCount.textContent = tryCount + '';
    setTimeout(function () {
        $popUp.classList.add('pop_up__open');
        $spinBox.classList.remove('active');
        $formBox.classList.add('active');
    }, 3500)
});

